"use strict";

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

const ENV_FILE = '.env.test';
const SYNC_URL = 'http://localhost:47301/api/ci-secret-sync';

// Read .env.test file
function readEnvFile() {
  return new Promise((resolve, reject) => {
    fs.readFile(path.join(__dirname, ENV_FILE), 'utf8', (err, data) => {
      if (err) {
        reject(err);
        return;
      }

      // Parse environment variables
      const vars = {};
      const lines = data.split('\n');
      for (const line of lines) {
        if (line.trim() && !line.startsWith('#')) {
          const [key, value] = line.split('=', 2);
          if (key && value) {
            vars[key.trim()] = value.trim();
          }
        }
      }
      resolve(vars);
    });
  });
}

// Post to CI secret sync endpoint
function postToCiSync(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': postData.length
      }
    };

    const req = http.request(SYNC_URL, options, (res) => {
      let responseData = '';
      res.on('data', (chunk) => responseData += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(responseData);
        } else {
          reject(new Error(`HTTP ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

// Main function
async function main() {
  try {
    const envVars = await readEnvFile();
    console.log(`Read ${Object.keys(envVars).length} environment variables from ${ENV_FILE}`);

    const response = await postToCiSync(envVars);
    console.log('CI secret sync successful:', response);
    process.exit(0);
  } catch (error) {
    console.error('CI secret sync failed:', error.message);
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main();
}

