async function secretSync() {
  try {
    // Read .env.test file
    const envContent = fs.readFileSync('.env.test', 'utf-8');

    // Parse into JSON object
    const envVars = {};
    envContent.split('\n').forEach(line => {
      const [key, value] = line.split('=');
      if (key && value) {
        envVars[key] = value;
      }
    });

    // Prepare the request
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/ci-secret-sync',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': postData.length
      }
    };

    // Make the request
    const req = https.request(options, (res) => {
      let responseData = '';
      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('CI secret-sync successful');
        } else {
          console.error('CI secret-sync failed:', responseData);
          process.exit(1);
        }
      });
    });

    req.on('error', (error) => {
      console.error('CI secret-sync error:', error);
      process.exit(1);
    });

    req.write(postData);
    req.end();

  } catch (error) {
    console.error('Error during CI secret-sync:', error);
    process.exit(1);
  }
}

