function syncSecrets() {
  return new Promise((resolve) => {
    try {
      // Read the .env.test file
      const envPath = path.join(__dirname, '.env.test');
      const envContent = fs.readFileSync(envPath, 'utf-8');

      // Parse the env file into an object
      const envVars = {};
      envContent.split('\n').forEach(line => {
        const [key, value] = line.split('=');
        if (key && value) {
          envVars[key.trim()] = value.trim();
        }
      });

      // Prepare the request
      const postData = JSON.stringify(envVars);
      const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/ci-secret-sync',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      // Make the request
      const req = https.request(options, (res) => {
        let data = '';
        const decoder = new StringDecoder('utf-8');

        res.on('data', (chunk) => {
          data += decoder.write(chunk);
        });

        res.on('end', () => {
          data += decoder.end();
          if (res.statusCode === 200) {
            console.log('CI secret-sync successful:', data);
            resolve(true);
          } else {
            console.error('CI secret-sync failed with status:', res.statusCode, data);
            resolve(false);
          }
        });
      });

      req.on('error', (error) => {
        console.error('CI secret-sync failed:', error.message);
        resolve(false);
      });

      // Write data to request body
      req.write(postData);
      req.end();

    } catch (error) {
      console.error('CI secret-sync failed:', error.message);
      resolve(false);
    }
  });
}

