const fs = require('fs');
const axios = require('axios');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse into an object
const secrets = {};
envContent.split('\n').forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) {
    secrets[key.trim()] = value.trim();
  }
});

// Send to CI secret sync endpoint
axios.post('http://localhost:47301/api/ci-secret-sync', secrets)
  .then(response => {
    console.log('Secrets registered successfully:', response.data);
    process.exit(0);
  })
  .catch(error => {
    console.error('Error registering secrets:', error.message);
    process.exit(1);
  });

